WITH RECURSIVE d(c, dep) AS (SELECT code, 0 FROM kg_point WHERE subject_id = CAST(:subject_id AS INTEGER) AND code NOT IN (SELECT point_code FROM kg_edge WHERE subject_id = CAST(:subject_id AS INTEGER)) UNION ALL SELECT e.point_code, d.dep + 1 FROM kg_edge e JOIN d ON e.pre_code = d.c WHERE e.subject_id = CAST(:subject_id AS INTEGER)) SELECT DISTINCT dep AS depth FROM (SELECT c, MAX(dep) AS dep FROM d GROUP BY c) ORDER BY depth
